"""Original oncology questions: tissue, stage, performance and imaging interpretation."""
from qbank_authoring import question,ref
rows=[]
NC=ref('NCI cancer diagnosis and staging','https://www.cancer.gov/about-cancer/diagnosis-staging')
GR=ref('NCI tumor grade','https://www.cancer.gov/about-cancer/diagnosis-staging/diagnosis/tumor-grade')
EC=ref('ECOG-ACRIN performance status reference','https://ecog-acrin.org/resources/ecog-performance-status/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('Imaging suggests metastatic solid cancer in a patient without a known primary. What is the usual diagnostic principle before systemic treatment?', 'Obtain appropriate tissue or cytological confirmation with enough material for relevant classification and biomarkers',[
 ('Imaging appearance alone identifies histology and every therapeutic target','Imaging cannot provide all of this information.'),('A serum tumor-marker panel universally replaces biopsy','Markers lack sufficient specificity and completeness.'),('Always biopsy the largest lesion even if it is the most hazardous site','Safety, yield and staging value guide site selection.')],
 'A cancer label must support a treatment decision','**Histological classification and biomarkers can change treatment profoundly.**',['Exceptions to tissue diagnosis exist in specific validated clinical settings.','Plan sample handling with pathology before an avoidable repeat procedure.'],'**Select a safe high-yield site and technique.**',['Consider whether a metastatic site can establish both diagnosis and extent.','Avoid empirical treatment that obscures tissue unless urgent circumstances justify it.'],[['Tissue','Lineage/histology'],['Biomarkers','Treatment selection'],['Site','Safety and diagnostic value']],[NC],style='clinical_scenario')

q('A patient has accessible lymphadenopathy and suspected lymphoma. Why may excisional or suitable core biopsy be preferred to FNA alone?', 'Tissue architecture and sufficient material can be necessary for classification and ancillary studies',[
 ('FNA always proves the exact lymphoma subtype','Cytology alone can be insufficient.'),('Architecture is irrelevant in all lymphoid disease','Architecture can be diagnostically important.'),('Any biopsy should be preceded by prolonged empirical corticosteroids','Steroids can obscure selected diagnoses and should not be routine before sampling.')],
 'The diagnostic question determines the sample','**Lymphoid classification often needs more than isolated cells.**',['Flow cytometry, immunohistochemistry and molecular studies may be required.','The best approach depends on site, safety and local expertise.'],'**Coordinate with pathology to preserve appropriate material.**',['Avoid placing every sample into a medium that prevents needed tests.','Urgent compressive emergencies may require a modified sequence.'],[['FNA','Limited architecture'],['Core/excision','More structural information'],['Planning','Ancillary-study requirements']],[ref('NICE non-Hodgkin lymphoma diagnostic guidance','https://www.nice.org.uk/guidance/ng52/chapter/Recommendations')],style='clinical_scenario')

q('A patient has a lung mass and an accessible suspicious supraclavicular node. Which biopsy strategy is often most useful?', 'Consider sampling the accessible node if it can safely establish diagnosis and relevant stage with adequate material',[
 ('Choose the most invasive lung procedure automatically','A safer site may answer the same diagnostic/staging questions.'),('Avoid metastatic-site tissue because it cannot inform treatment','It often provides useful classification and biomarkers.'),('Use a negative serum marker to cancel tissue investigation','That does not exclude malignancy.')],
 'A good biopsy can answer more than one question','**Site selection balances safety, yield and staging information.**',['Adequate tumor content and preservation matter for molecular tests.','A nondiagnostic sample may need a different approach.'],'**Plan through the relevant multidisciplinary pathway.**',['Correlate pathology with imaging to avoid a misleading unrelated lesion.','Discuss tissue needs before the procedure.'],[['Accessible node','Potential low-risk high-value sample'],['Adequacy','Histology and biomarkers'],['Correlation','Imaging/pathology consistency']],[NC],style='clinical_scenario')

q('A poorly differentiated tumor stains for broad cytokeratins. What is the most appropriate inference?', 'Epithelial differentiation is supported, but a panel and clinical context are needed for final classification',[
 ('The stain alone identifies the exact primary organ','Cytokeratins are not organ-specific by themselves.'),('Every cytokeratin-positive tumor must be a benign lesion','Many carcinomas express them.'),('One stain eliminates the need to consider unusual mimics','Aberrant expression and technical issues require contextual interpretation.')],
 'Immunohistochemistry is a pattern-based tool','**Lineage markers narrow the differential rather than independently solving every primary-site question.**',['Additional markers and morphology refine classification.','Sample quality and tumor heterogeneity can affect results.'],'**Integrate pathology with the clinical distribution.**',['Avoid an indiscriminate marker panel without a focused differential.','Preserve tissue for predictive testing when needed.'],[['Cytokeratin','Epithelial clue'],['Panel','Refines lineage/site'],['Diagnosis','Morphology plus context']],[NC])

q('What is the principal distinction between tumor grade and stage?', 'Grade describes biological/microscopic differentiation features, while stage describes extent of disease',[
 ('Grade and stage are interchangeable terms','They answer different questions.'),('Grade is always determined only by tumor diameter','Size is one possible staging component rather than a universal grade definition.'),('Stage measures only cell differentiation','Extent and spread are central to staging.')],
 'Two independent dimensions inform prognosis and treatment','**A small localized tumor can be high grade, and a low-grade tumor can be extensive.**',['Grading systems differ by tumor type.','Stage systems can include anatomy and selected nonanatomical factors.'],'**Use the specific disease classification.**',['Do not compare grading numbers across unrelated cancers as if identical.','Read the full pathology and staging context.'],[['Grade','Microscopic/biological features'],['Stage','Extent/spread'],['Use','Complementary information']],[GR,NC])

q('In TNM nomenclature, what does the M category describe?', 'Distant metastasis status',[
 ('Regional lymph-node involvement','This is the N component.'),('Primary tumor extent','This is the T component.'),('Histological mitotic count in every tumor','That is not the M category.')],
 'Keep the components of anatomical staging separate','**T, N and M describe different dimensions.**',['Definitions are site-specific and edition-dependent.','Not every cancer uses TNM.'],'**Use the correct tumor-specific staging system.**',['Do not equate regional nodes automatically with distant spread.','Document the evidence and timing of staging.'],[['T','Primary tumor'],['N','Regional nodes'],['M','Distant metastasis']],[NC])

q('What does a “yp” prefix on a pathological TNM category indicate?', 'Pathological assessment after preoperative systemic and/or radiation treatment',[
 ('Untreated clinical staging before any therapy','That is a different classification context.'),('A recurrence category independent of prior therapy','The prefix specifically reflects post-treatment assessment.'),('A pediatric-only stage','The letter does not mean young patient.')],
 'Treatment changes how a stage should be interpreted','**Post-neoadjuvant pathology is not identical to untreated pathological stage.**',['Clinical baseline and treatment response remain relevant.','Use the exact notation and edition in the report.'],'**Compare like staging contexts when interpreting outcomes.**',['Do not erase the pretreatment disease extent.','Review residual tumor and nodal response separately.'],[['c','Clinical assessment'],['p','Pathological assessment'],['yp','Pathology after preoperative treatment']],[NC])

q('What is a sentinel lymph node?', 'A node or nodes first receiving lymphatic drainage from a tumor region, identified by a validated mapping procedure',[
 ('Any largest palpable node regardless of drainage','Size does not define sentinel status.'),('Every node in a full regional dissection','Sentinel sampling is more selective.'),('A distant metastatic node by definition','The concept concerns mapped lymphatic drainage.')],
 'Mapping identifies a drainage pathway rather than simply a size','**Sentinel sampling can stage selected cancers with less morbidity than routine full dissection.**',['Eligibility, technique and interpretation depend on the tumor and setting.','A negative result is not a universal guarantee of no recurrence.'],'**Apply the disease-specific protocol.**',['Prior surgery or neoadjuvant treatment can change the pathway.','Do not extrapolate one cancer’s node-management rules to all others.'],[['Sentinel','Mapped first drainage'],['Purpose','Selected regional staging'],['Limits','Protocol and tumor context']],[ref('NCI sentinel lymph-node biopsy','https://www.cancer.gov/about-cancer/diagnosis-staging/staging/sentinel-node-biopsy-fact-sheet')])

q('A patient can perform personal care and is out of bed for most of the day, but cannot work. Which ECOG performance status is most consistent?', '2',[
 ('0','This indicates unrestricted activity.'),('1','This generally permits light work despite restriction of strenuous activity.'),('3','This indicates more limited self-care and bed/chair confinement for most waking time.')],
 'Performance status describes observed function','**ECOG two reflects preserved self-care with inability to work.**',['Determine the usual recent state and reversible contributors.','Do not substitute age for function.'],'**Use performance with organ function, goals and treatment-specific evidence.**',['A number alone should not replace an individualized decision.','Reassess after reversible illness is treated.'],[['Self-care','Preserved'],['Work','Unable'],['Time up','Most waking hours']],[EC],style='clinical_scenario')

q('A patient performs only limited personal care and spends most waking hours in bed or a chair. Which ECOG status best fits?', '3',[
 ('1','This describes a substantially more active patient.'),('2','This generally preserves self-care and more time up.'),('4','This denotes complete disability rather than the limited self-care described.')],
 'Functional categories require a concrete activity history','**The balance of self-care and waking activity distinguishes adjacent categories.**',['Ask about daily tasks rather than using appearance alone.','Acute reversible complications can temporarily worsen the score.'],'**Integrate the score with treatment goals and likely benefit.**',['Avoid automatically equating poor status with irreversible cancer progression.','Consider supportive interventions and reassessment.'],[['Self-care','Limited'],['Bed/chair','Most waking time'],['Category','ECOG 3']],[EC],style='clinical_scenario')

q('A PET-CT shows an FDG-avid node soon after an infection. Which interpretation is most appropriate?', 'Inflammation can cause FDG uptake, so avidity alone does not prove malignancy',[
 ('All FDG uptake is tumor-specific','Activated inflammatory cells also use glucose.'),('A high standardized uptake value identifies the exact histology','SUV is not a histological assay.'),('The scan must be ignored because inflammation is possible','The result remains useful when integrated with context and confirmation.')],
 'Metabolic activity is not synonymous with cancer','**FDG uptake reflects cellular glucose handling.**',['Timing, distribution and anatomical findings matter.','Sampling or interval reassessment may be needed if the result changes management.'],'**Correlate with the clinical question.**',['Do not stage up a patient from an unverified ambiguous focus when confirmation is important.','Review treatment and infection history.'],[['FDG','Metabolic signal'],['False positive','Inflammatory activity'],['Decision','Context and verification']],[NC],style='clinical_scenario')

q('A suspicious small lesion is not FDG-avid. Which statement is correct?', 'Malignancy remains possible because small size and low-avidity tumor biology can produce a negative PET result',[
 ('Negative FDG uptake excludes all cancer','Sensitivity varies by size and tumor type.'),('The result proves a benign cyst','Anatomical characterization is still required.'),('Every tumor sheds enough FDG signal to be detected regardless of size','Partial-volume and biological limitations matter.')],
 'A negative metabolic test has a defined detection range','**Low uptake is not a universal rule-out criterion.**',['Some tumor subtypes are less FDG-avid.','Small lesions may fall below reliable detection.'],'**Use the anatomical and clinical risk assessment.**',['Choose biopsy, surveillance or another modality according to the case.','Do not discard a concerning lesion solely from PET negativity.'],[['Small lesion','Resolution limitation'],['Low-avidity biology','Limited signal'],['Next step','Risk-based assessment']],[NC])
